template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{40} \def\angleb{140} \def\showchord{1} \def\showaxis{1} \def\axisdashed{0} \def\showaxisends{1} \def\showom{1} \def\showperp{1} \def\showmidpoint{1} \def\showequalmark{0} \def\showarcmark{0} \def\showradii{0} \def\showrotation{0} \def\showcentralsym{0} \def\showcenter{1} \def\labela{A} \def\labelb{B} \def\labelm{M} \def\labelaxisc{C} \def\labelaxisd{D} \def\labelsym{E} \def\showcoord{0} \def\cx{0} \def\cy{0}
% 视觉归一化：区分坐标模式与裸图模式
\ifnum\showcoord>0
  \pgfmathtruncatemacro{\xleft}{floor(\cx - \radius - 0.8)}
  \pgfmathtruncatemacro{\xright}{ceil(\cx + \radius + 0.8)}
  \pgfmathtruncatemacro{\ybottom}{floor(\cy - \radius - 0.8)}
  \pgfmathtruncatemacro{\ytop}{ceil(\cy + \radius + 0.8)}
  \pgfmathsetmacro{\xrange}{\xright - \xleft}
  \pgfmathsetmacro{\yrange}{\ytop - \ybottom}
  \pgfmathsetmacro{\figscale}{6.0 / max(\xrange, \yrange)}
\else
  \pgfmathsetmacro{\figscale}{3 / \radius}
\fi
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
% A、B 在圆上；垂直平分弦的直径方向 axang 取 A、B 位置角的中点方向。
% 该直径必垂直平分弦 AB —— 这既是垂径定理的图形，也是圆的一条对称轴。
\pgfmathsetmacro{\Ax}{\radius*cos(\anglea)}
\pgfmathsetmacro{\Ay}{\radius*sin(\anglea)}
\pgfmathsetmacro{\Bx}{\radius*cos(\angleb)}
\pgfmathsetmacro{\By}{\radius*sin(\angleb)}
\pgfmathsetmacro{\axang}{(\anglea + \angleb)/2}
% M = AB 中点（垂足），必在该直径上；S = A 关于圆心的对称点（中心对称）
\pgfmathsetmacro{\Mx}{(\Ax + \Bx)/2}
\pgfmathsetmacro{\My}{(\Ay + \By)/2}
\pgfmathsetmacro{\Sx}{-\Ax}
\pgfmathsetmacro{\Sy}{-\Ay}
% 半弦长 = radius*sin((angleb-anglea)/2)，约束保证其 > 0（A、B 不重合）
\pgfmathsetmacro{\halfab}{\radius*sin((\angleb - \anglea)/2)}
% 弦心距的有向长度 = radius*tcos；tcos 的符号决定 M 落在直径的哪一侧
\pgfmathsetmacro{\tcos}{cos((\angleb - \anglea)/2)}
% 由 M 指向圆心的单位向量（沿该直径）。AB 恰为直径时 M 与 O 重合，取任一侧都不影响正确性。
\pgfmathsetmacro{\tsign}{(\tcos < 0) ? 1 : -1}
\pgfmathsetmacro{\wmx}{\tsign*cos(\axang)}
\pgfmathsetmacro{\wmy}{\tsign*sin(\axang)}
% A->B 的单位向量（弦方向）
\pgfmathsetmacro{\vabx}{(\Bx - \Ax)/(2*\halfab)}
\pgfmathsetmacro{\vaby}{(\By - \Ay)/(2*\halfab)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
    % ===== 坐标系（showcoord=1 时绘制）=====
  \ifnum\showcoord>0
    \draw[->, thick] (\xleft-0.5, 0) -- (\xright+0.5, 0) node[right] {$x$};
    \draw[->, thick] (0, \ybottom-0.5) -- (0, \ytop+0.5) node[above] {$y$};
  \fi
  \coordinate (O) at (\cx,\cy);
  \coordinate (A) at ({\cx+\Ax},{\cy+\Ay});
  \coordinate (B) at ({\cx+\Bx},{\cy+\By});
  \coordinate (M) at ({\cx+\Mx},{\cy+\My});
  \coordinate (S) at ({\cx+\Sx},{\cy+\Sy});
  \coordinate (C) at ({\cx+\radius*cos(\axang)},{\cy+\radius*sin(\axang)});
  \coordinate (D) at ({\cx-\radius*cos(\axang)},{\cy-\radius*sin(\axang)});
  % 圆
  \draw[thick] (O) circle [radius=\radius];
  % 垂直平分弦的直径 CD；axisdashed 打开时画成略微伸出圆外的虚线，用于强调它是对称轴
  \ifnum\showaxis>0
    \ifnum\axisdashed>0
      \pgfmathsetmacro{\axl}{1.06*\radius}
      \draw[thick, dashed] ({\cx-\axl*cos(\axang)},{\cy-\axl*sin(\axang)}) -- ({\cx+\axl*cos(\axang)},{\cy+\axl*sin(\axang)});
    \else
      \draw[thick] (C) -- (D);
    \fi
  \fi
  % 弦 AB
  \ifnum\showchord>0
    \draw[thick] (A) -- (B);
  \fi
  % 弦心距 OM（圆心到弦的垂线段）
  \ifnum\showom>0
    \draw[thick] (O) -- (M);
  \fi
  % 半径 OA、OB
  \ifnum\showradii>0
    \draw[thick] (O) -- (A);
    \draw[thick] (O) -- (B);
  \fi
  % 中心对称：直径 AS（S 是 A 关于圆心的对称点）
  \ifnum\showcentralsym>0
    \draw[thick] (A) -- (S);
    \fill (S) circle [radius=\dotr pt];
    \node at ({\cx+1.15*\Sx},{\cy+1.15*\Sy}) {$\labelsym$};
  \fi
  % 旋转角 ∠AOB 的角弧（A 绕 O 逆时针旋转该角后与 B 重合）
  \ifnum\showrotation>0
    \pgfmathsetmacro{\rarc}{min(0.55/\figscale, \radius*0.3)}
    \draw[thick] ({\cx+\rarc*cos(\anglea)},{\cy+\rarc*sin(\anglea)}) arc[start angle=\anglea, end angle=\angleb, radius=\rarc];
  \fi
  % 垂足 M 处直角记号（直径垂直于弦，记号朝圆心一侧）
  \ifnum\showperp>0
    \pgfmathsetmacro{\rms}{min(0.24/\figscale, \radius*0.12, \halfab*0.3)}
    \draw[thick] ({\cx+\Mx+\rms*\vabx},{\cy+\My+\rms*\vaby}) -- ({\cx+\Mx+\rms*\vabx+\rms*\wmx},{\cy+\My+\rms*\vaby+\rms*\wmy}) -- ({\cx+\Mx+\rms*\wmx},{\cy+\My+\rms*\wmy});
  \fi
  % AM=MB 等长记号（垂直于弦的短划）
  \ifnum\showequalmark>0
    \pgfmathsetmacro{\tk}{min(0.16/\figscale, \halfab*0.28)}
    \pgfmathsetmacro{\qax}{(\Ax + \Mx)/2}
    \pgfmathsetmacro{\qay}{(\Ay + \My)/2}
    \pgfmathsetmacro{\qbx}{(\Bx + \Mx)/2}
    \pgfmathsetmacro{\qby}{(\By + \My)/2}
    \draw[thick] ({\cx+\qax - \tk*\vaby},{\cy+\qay + \tk*\vabx}) -- ({\cx+\qax + \tk*\vaby},{\cy+\qay - \tk*\vabx});
    \draw[thick] ({\cx+\qbx - \tk*\vaby},{\cy+\qby + \tk*\vabx}) -- ({\cx+\qbx + \tk*\vaby},{\cy+\qby - \tk*\vabx});
  \fi
  % 弧 AC = 弧 BC 的等量记号（C 平分弦 AB 所对的弧，记号画在两段弧的中点处）
  \ifnum\showarcmark>0
    \pgfmathsetmacro{\tka}{min(0.18/\figscale, \radius*0.1)}
    \pgfmathsetmacro{\mlft}{(\anglea + \axang)/2}
    \pgfmathsetmacro{\mrgt}{(\angleb + \axang)/2}
    \draw[thick] ({\cx+(\radius-\tka)*cos(\mlft)},{\cy+(\radius-\tka)*sin(\mlft)}) -- ({\cx+(\radius+\tka)*cos(\mlft)},{\cy+(\radius+\tka)*sin(\mlft)});
    \draw[thick] ({\cx+(\radius-\tka)*cos(\mrgt)},{\cy+(\radius-\tka)*sin(\mrgt)}) -- ({\cx+(\radius+\tka)*cos(\mrgt)},{\cy+(\radius+\tka)*sin(\mrgt)});
  \fi
  % 垂足（弦中点）M
  \ifnum\showmidpoint>0
    \fill (M) circle [radius=\dotr pt];
    \node at ({\cx+\Mx - 0.17*\radius*\wmx},{\cy+\My - 0.17*\radius*\wmy}) {$\labelm$};
  \fi
  % 直径（对称轴）的两个端点 C、D（C 在 axang 方向，与弧记号同侧）
  \ifnum\showaxisends>0
    \fill (C) circle [radius=\dotr pt];
    \fill (D) circle [radius=\dotr pt];
    \node at ({\cx+1.15*\radius*cos(\axang)},{\cy+1.15*\radius*sin(\axang)}) {$\labelaxisc$};
    \node at ({\cx-1.15*\radius*cos(\axang)},{\cy-1.15*\radius*sin(\axang)}) {$\labelaxisd$};
  \fi
  % 弦端点 A、B（字母沿半径方向外推，避免压线）
  \fill (A) circle [radius=\dotr pt];
  \node at ({\cx+1.15*\Ax},{\cy+1.15*\Ay}) {$\labela$};
  \fill (B) circle [radius=\dotr pt];
  \node at ({\cx+1.15*\Bx},{\cy+1.15*\By}) {$\labelb$};
  % 圆心 O
  \ifnum\showcenter>0
    \fill (O) circle [radius=\dotr pt];
    \node[below left=2pt] at (O) {$O$};
  \fi
\end{tikzpicture}
